result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tlv.py", "content": """"TLV (tag-length-value) codec modeled on DER structure.

Node forms:
    ('prim', tag, payload_bytes)  -- primitive: tag byte with bit 5 (0x20) clear
    ('cons', tag, [children])     -- constructed: bit 5 set, children concatenated

Length encoding is definite only:
    short form: length < 128 -> single byte
    long form:  0x81 prefix for 1-byte length (128..255)
                0x82 prefix for 2-byte length (256..65535)

Tag byte layout: [constructed bit 0x20] | tag number in low bits.
Tag numbers must fit in the low 5 bits (0..31).
"""

PRIM = "prim"
CONS = "cons"

CONSTRUCTED_BIT = 0x20
TAG_NUMBER_MASK = 0x1F


class TLVError(Exception):
    """Base class for all TLV decoding errors."""


class TrailingDataError(TLVError):
    pass


class ValueTruncatedError(TLVError):
    pass


class ChildOverrunError(TLVError):
    pass


def _check_tag(tag):
    if not isinstance(tag, int) or isinstance(tag, bool):
        raise TypeError("tag must be an int")
    if not 0 <= tag <= TAG_NUMBER_MASK:
        raise ValueError(f"tag number {tag} out of range 0..31")


def encode(node):
    """Encode a node tree into bytes."""
    kind, tag = node[0], node[1]
    _check_tag(tag)
    if kind == PRIM:
        payload = node[2]
        if not isinstance(payload, (bytes, bytearray)):
            raise TypeError("primitive payload must be bytes")
        return bytes([tag]) + _encode_length(len(payload)) + bytes(payload)
    if kind == CONS:
        body = b"".join(encode(child) for child in node[2])
        return bytes([tag | CONSTRUCTED_BIT]) + _encode_length(len(body)) + body
    raise ValueError(f"unknown node kind {kind!r}")


def _encode_length(n):
    if n < 0x80:
        return bytes([n])
    if n <= 0xFF:
        return b"\x81" + bytes([n])
    if n <= 0xFFFF:
        return b"\x82" + bytes([n >> 8 & 0xFF, n & 0xFF])
    raise ValueError("length too long for definite form (max 65535)")


def decode(data):
    """Decode exactly one top-level TLV; any leftover bytes are an error."""
    node, offset = _decode_one(data, 0)
    if offset != len(data):
        raise TrailingDataError(
            f"trailing garbage after top-level TLV at offset {offset} "
            f"({len(data) - offset} unexpected byte(s))"
        )
    return node


def _decode_length(data, offset):
    """Return (length, next_offset)."""
    if offset >= len(data):
        raise ValueTruncatedError(
            f"truncated value: missing length byte at offset {offset}"
        )
    first = data[offset]
    offset += 1
    if first < 0x80:
        return first, offset
    if first == 0x80:
        raise ValueError("indefinite length not supported at offset %d" % (offset - 1))
    num_bytes = first & 0x7F
    if num_bytes > 2:
        raise ValueError(f"unsupported long-form length of {num_bytes} bytes at offset {offset - 1}")
    if offset + num_bytes > len(data):
        raise ValueTruncatedError(
            f"truncated value: long-form length needs {num_bytes} byte(s) "
            f"but only {len(data) - offset} available at offset {offset}"
        )
    length = int.from_bytes(data[offset : offset + num_bytes], "big")
    return length, offset + num_bytes


def _decode_one(data, offset):
    """Decode one TLV starting at offset; return (node, end_offset)."""
    start = offset
    if offset >= len(data):
        raise ValueTruncatedError(f"truncated value: no tag byte at offset {offset}")
    tag_byte = data[offset]
    tag = tag_byte & TAG_NUMBER_MASK
    header_len = 1
    length, offset = _decode_length(data, offset + 1)
    header_len = offset - start
    end = offset + length

    if not tag_byte & CONSTRUCTED_BIT:
        if end > len(data):
            raise ValueTruncatedError(
                f"truncated value: primitive tag {tag} declares {length} byte(s) "
                f"but only {len(data) - offset} available at offset {start}"
            )
        return (PRIM, tag, bytes(data[offset:end])), end

    # Constructed: children must tile the content exactly.
    children = []
    pos = offset
    while pos < end:
        child, child_end = _decode_one(data, pos)
        if child_end > end:
            raise ChildOverrunError(
                f"child TLV ending at offset {child_end} overruns parent "
                f"boundary {end} (parent starts at offset {start})"
            )
        children.append(child)
        pos = child_end
    return (CONS, tag, children), end
